"""Registrar leituras e inspeção visual do lote B2-06 (registro 124)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['paginacao_revista'];N=len(m['paginas']);assert N==11
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,12))-{3},same
notes={1:'Abertura da febre, aviso e quadro de transmissão em largura inteira.',2:'Continuação do quadro com cabeçalho repetido; crises, tratamento.',3:'Tentativas, isolamento e quadro do exemplo por horário; ressalva sobre esta Rina.',4:'Fim da febre e abertura da ficha preenchida na mesma página; quadro dos participantes.',5:'Quadro largo das ameaças; atuação, prioridades, retirada e derrota.',6:'Fio de impulso em quadro largo e começo do quadro de lugar e sinais.',7:'Fim do quadro com cabeçalho repetido; antes de jogar e resultado final.',8:'Fim da ficha e abertura do chefe na mesma página; quadro da conferência e começo das configurações.',9:'Configurações com cabeçalho repetido; mapa do portão junto do exemplo de Preparar.',10:'Exemplo de Preparar, turnos para responder e começo das mudanças.',11:'Fim das mudanças e escolha do exemplo; fechamento.'}
save('revisao-final.json',{'registro':124,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das três fontes e das consultas citadas, três cópias, remissões, clareza e o nome do Carregador.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura integral das onze páginas da prova paginada e pente fino.'}],'ajuste_de_diagramacao':'Primeira prova com 12 páginas e duas quase vazias; casos curtos passam a seguir na mesma página, como na prova 121, e quadros a partir de cinco linhas podem continuar com cabeçalho repetido.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if i==3 else 'Inspeção direta na paginação final; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Vazios curtos antes de quadros largos serão reavaliados na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s103':[1,4],'s077':[4,8],'s068':[8,11]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e consultas pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':124,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':124,'lote':'B2-06','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':33,'casos_pendentes':26,'lotes_pendentes':6,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B3-01','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':3},ensure_ascii=False))
